#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct { int to, t, p, next; } Edge;
typedef struct { int d, id; } HN;

static Edge *E;
static int *head;
static int C, N;
static int *dist;
static char *vis;
static HN *heap;
static int hn;

static void hpush(int d, int id) {
    int i = hn++;
    heap[i].d = d; heap[i].id = id;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (heap[p].d <= heap[i].d) break;
        HN tmp = heap[p]; heap[p] = heap[i]; heap[i] = tmp;
        i = p;
    }
}

static HN hpop(void) {
    HN top = heap[0];
    heap[0] = heap[--hn];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, s = i;
        if (l < hn && heap[l].d < heap[s].d) s = l;
        if (r < hn && heap[r].d < heap[s].d) s = r;
        if (s == i) break;
        HN tmp = heap[s]; heap[s] = heap[i]; heap[i] = tmp;
        i = s;
    }
    return top;
}

int main(void) {
    int V, M;
    if (scanf("%d %d %d", &V, &N, &M) != 3) return 0;
    C = V + 1;

    E = malloc(sizeof(Edge) * 2 * (size_t)M);
    head = malloc(sizeof(int) * (size_t)(N + 1));
    for (int i = 0; i <= N; i++) head[i] = -1;

    for (int i = 0; i < M; i++) {
        int a, b, t, p;
        scanf("%d %d %d %d", &a, &b, &t, &p);
        E[2 * i]     = (Edge){ b, t, p, head[a] }; head[a] = 2 * i;
        E[2 * i + 1] = (Edge){ a, t, p, head[b] }; head[b] = 2 * i + 1;
    }

    int X, Y;
    scanf("%d %d", &X, &Y);

    long total = (long)(N + 1) * C;
    dist = malloc(sizeof(int) * (size_t)total);
    vis  = malloc((size_t)total);
    for (long i = 0; i < total; i++) { dist[i] = INT_MAX; vis[i] = 0; }

    /* max pushes <= 1 + sum over directed edges of (V+1) ~ 804k; allocate safely */
    heap = malloc(sizeof(HN) * 2200000);
    hn = 0;

    long sid = (long)X * C;
    dist[sid] = 0;
    hpush(0, (int)sid);

    int ans = -1;
    while (hn > 0) {
        HN cur = hpop();
        if (vis[cur.id]) continue;
        vis[cur.id] = 1;
        int u = cur.id / C, c = cur.id - u * C;
        if (u == Y) { ans = cur.d; break; }
        for (int e = head[u]; e != -1; e = E[e].next) {
            int nc = c + E[e].p;
            if (nc <= V) {
                int nd = cur.d + E[e].t;
                long nid = (long)E[e].to * C + nc;
                if (nd < dist[nid]) {
                    dist[nid] = nd;
                    hpush(nd, (int)nid);
                }
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}
